    def setscale(self):
        _translate = QtCore.QCoreApplication.translate
        if self.radioButton_uv.isChecked():
            self.scale = "μV"
        elif self.radioButton_mv.isChecked():
            self.scale = "mV"

    def set_channels(self):
        self.selected_channels = []
        for checkbox in self.scrollAreaWidgetContents.findChildren(QtWidgets.QCheckBox):
            if checkbox.isChecked():
                self.selected_channels.append(checkbox.text())

    def apply_config(self):

        self.set_channels()
        if not self.selected_channels:
            QtWidgets.QMessageBox.warning(None, "Configuration Error", "Please select at least one channel.")
            return
        # 读取label_uvmv的文本值并赋给self.scale
        #self.scale = self.label_uvmv.text()
        if not self.scale:
            QtWidgets.QMessageBox.warning(None, "Configuration Error", "Please select the amplitude unit (μV or mV).")
            return  

        # 读取lineEdit_yaxis的值，如果是正数则赋值给self.scale_amplitude，否则弹出警告框
        try:
            self.scale_amplitude = float(self.lineEdit_yaxis.text())
            if self.scale_amplitude <= 0:
                raise ValueError("Y轴限制必须为正数。")
        except ValueError:
            QtWidgets.QMessageBox.warning(None, "Configuration Error", "Y-axis limits must be positive.")
            return  

        # 读取lineEdit_winsize的值，如果是正数则赋值给self.winsize，否则弹出警告框
        try:
            self.winsize = float(self.lineEdit_winsize.text())
            if self.winsize <= 0:
                raise ValueError("窗口大小必须为正数。")
        except ValueError:
            QtWidgets.QMessageBox.warning(None, "Configuration Error", "Window size must be positive.")
            return  
        
        # 读取lineEdit_H和lineEdit_W的值，计算宽高比，如果两者都是正数则计算H/W比例
        try:
            H = float(self.lineEdit_H.text())
            W = float(self.lineEdit_W.text())
            if H <= 0 or W <= 0:
                raise ValueError("高度和宽度必须为正数。")
            self.HWratio = H / W
        except ValueError:
            QtWidgets.QMessageBox.warning(None, "Configuration Error", "Height and width must be positive.")
            return  

        # 读取lineEdit_TIME的值，如果是正数则赋值给self.timeinterval，否则弹出警告框
        try:
            self.timeinterval = float(self.lineEdit_TIME.text())
            if self.timeinterval <= 0:
                raise ValueError("Time interval must be positive.")
            # Check if the time interval exceeds the total duration
            if self.timeinterval > self.raw.n_times / self.raw.info['sfreq']:
                raise ValueError("Time interval exceeds the total duration")
        except ValueError as e:
            QtWidgets.QMessageBox.warning(None, "Configuration Error", str(e))
            return 

        # 如果所有输入都有效，则执行以下操作
        self.rms_window = QtWidgets.QWidget()
        self.rms_ui = Ui_RMS()
        self.rms_ui.import_raw(self.raw)
        self.rms_ui.setupUi(self.rms_window)
        self.rms_ui.apply_rms(self.selected_channels, self.scale, self.scale_amplitude, self.winsize, self.HWratio, self.timeinterval)
        self.rms_window.show()


