    def import_raw(self,raw):
        self.raw = raw
        self.raw_processed = self.raw.copy()

    def apply_rms(self,selected_channels, scale, scale_amplitude, winsize, HWratio, timeinterval):
        self.figure.clear()
        data = self.raw.get_data()
        # 计算需要的子图数量
        axs = self.figure.subplots(len(selected_channels), 1)
        if len(selected_channels) == 1:
            axs = [axs]  # 确保axs是列表

        # 设置 RMS 计算的时间窗口长度
        sfreq = self.raw.info['sfreq'] 
        window_size = int(sfreq * winsize)  

        # 根据scale设置数据单位转换因子
        unit_multiplier = 1
        unit_label = ""
        if scale == 'mV':
            unit_multiplier = 1000
            unit_label = 'mV'
        elif scale == 'μV':
            unit_multiplier = 1000000
            unit_label = 'μV'

        self.rms_data = {'Channel': [], 'Time': [], 'RMS': []}

        for idx, channel in enumerate(selected_channels):
            channel_index = self.raw.info['ch_names'].index(channel)
            channel_data = data[channel_index]  # 获取当前通道的数据

            rms = []
            times = []
            for start in range(0, len(channel_data) - window_size, window_size):
                end = start + window_size
                segment = channel_data[start:end]  # 从channel_data中截取窗口数据

                rms_value = np.sqrt(np.mean(segment ** 2)) * unit_multiplier
                rms.append(rms_value)
                times.append(self.raw.times[start])
            # 将当前通道的数据加入 self.rms_data
            self.rms_data['Channel'].extend([channel] * len(times))
            self.rms_data['Time'].extend(times)
            self.rms_data['RMS'].extend(rms)

            axs[idx].plot(times, rms, label=f'RMS of {channel}')
            axs[idx].set_title(f"Channel: {channel}")
            axs[idx].set_ylim([-scale_amplitude, scale_amplitude])  # 设置y轴上下限
            axs[idx].xaxis.set_major_locator(plt.MultipleLocator(timeinterval))  # 设置x轴刻度间隔
            axs[idx].legend()

            # 在第一个子图添加单位标签
            if idx == 0:
                axs[idx].annotate(unit_label, xy=(0.05, 0.95), xycoords='axes fraction', fontsize=12, 
                                ha='left', va='top')
        # 固定子图宽度和高度（像素）
        subplot_width_px = 2000
        subplot_height_px = 2000 / HWratio
        total_height_px = subplot_height_px * len(selected_channels)

        # 调整画布的尺寸以适应所有子图
        self.figure.subplots_adjust(left=None, bottom=0.02, right=None, top=0.98, wspace=None, hspace=0.5)
        self.figure.set_size_inches(subplot_width_px / self.figure.dpi, total_height_px / self.figure.dpi, forward=True)
        self.canvas.resize(subplot_width_px, int(total_height_px))
        self.canvas.draw()
        

    def save_csv(self):
        options = QFileDialog.Options()
        fileName, _ = QFileDialog.getSaveFileName(self.window, "Save CSV", "", "CSV Files (*.csv);;All Files (*)", options=options)
        if fileName:
            df = pd.DataFrame(self.rms_data)
            df.to_csv(fileName, index=False)
            QtWidgets.QMessageBox.information(self.window, "File Saved", "Data saved successfully!")


    def save_figure(self):
        options = QFileDialog.Options()
        fileName, _ = QFileDialog.getSaveFileName(self.window, "Save Figure", "",
                                                "PNG Files (*.png);;SVG Files (*.svg);;All Files (*)", options=options)
        if fileName:
            self.figure.savefig(fileName)
            QtWidgets.QMessageBox.information(self.window, "File Saved", "Figure saved successfully!")